//! Renders the module wrapper and Rust expression syntax.

use std::{
    collections::BTreeMap,
    fmt::{self, Write as _},
};

use baml_compiler2_mir::BinOp;

use crate::{admit::CompiledFunction, analysis::Repr};

const PRELUDE: &str = "\
//! Generated by `baml_compiler2_rust`. Do not edit.
#![allow(unused_imports, unused_mut, unused_variables, unused_assignments, unused_labels,
    unused_parens, unreachable_code, unreachable_patterns, non_snake_case, clippy::all,
    clippy::pedantic)]
use bex_vm::{BexVm, NativeFunction, CompiledBodyTable, errors::VmError};
use bex_vm::compiled_rt::{CompiledEntry, Step};
use bex_vm_types::{BinOp, CmpOp, GlobalIndex, ObjectIndex, RealizedTy, Value};
type R<T> = Result<T, Box<VmError>>;
";

pub(crate) fn render_module(
    bodies: &str,
    functions: &[CompiledFunction],
    builtins: &BTreeMap<String, usize>,
    artifact_path: &str,
    fingerprint: [u8; 32],
) -> String {
    let mut out = String::from(PRELUDE);
    write_module(
        &mut out,
        bodies,
        functions,
        builtins,
        artifact_path,
        fingerprint,
    )
    .expect("formatting into a String cannot fail");
    out
}

fn write_module(
    out: &mut String,
    bodies: &str,
    functions: &[CompiledFunction],
    builtins: &BTreeMap<String, usize>,
    artifact_path: &str,
    fingerprint: [u8; 32],
) -> fmt::Result {
    // A builtin the VM does not bind is an internal error, not a panic.
    for (key, ordinal) in builtins {
        writeln!(
            out,
            "fn builtin_{ordinal}() -> R<NativeFunction> {{
                static F: std::sync::OnceLock<Option<NativeFunction>> = std::sync::OnceLock::new();
                F.get_or_init(|| bex_vm::package_baml::resolve_native({key:?})).ok_or_else(|| {{
                    Box::new(VmError::from(bex_vm::errors::VmInternalError::CompiledBody {{
                        message: String::from(\"the VM binds no builtin {key}\"),
                    }}))
                }})
            }}"
        )?;
    }
    out.push_str(bodies);
    writeln!(
        out,
        "pub static COMPILED_BODIES: CompiledBodyTable = CompiledBodyTable {{
            fingerprint: {fingerprint:?},
            entries: &["
    )?;
    for function in functions {
        writeln!(
            out,
            "CompiledEntry {{ object: {}, name: {:?}, arity: {}, body: {}, \
             slots: {}, cause_slot: {:?} }},",
            function.object,
            function.name,
            function.arity,
            function.symbol,
            function.slots,
            function.cause_slot,
        )?;
    }
    writeln!(out, "] }};")?;
    writeln!(
        out,
        "pub static PROGRAM_ARTIFACT: &[u8] = include_bytes!({artifact_path:?});"
    )
}

pub(crate) fn coerce(code: &str, from: Repr, to: Repr) -> String {
    use Repr::{Bool, Float, Int, Value};
    match (from, to) {
        (a, b) if a == b => code.to_string(),
        (Int, Value) => format!("Value::int({code})"),
        (Bool, Value) => format!("Value::bool({code})"),
        (Float, Value) => format!("vm.float_value({code})"),
        // Reject wrong value kinds instead of silently converting them.
        (Value, Int) => format!("bex_vm::compiled_rt::expect_int({code})?"),
        (Value, Bool) => format!("bex_vm::compiled_rt::expect_bool({code})?"),
        (Value, Float) => format!("bex_vm::compiled_rt::expect_f64({code})?"),
        // Scalars of different kinds never flow into one another in checked
        // MIR; go through the tagged form so the VM's own rule decides.
        (a, b) => coerce(&coerce(code, a, Value), Value, b),
    }
}

pub(crate) fn float_literal(f: f64) -> String {
    if f.is_nan() {
        "f64::NAN".to_string()
    } else if f.is_infinite() {
        if f > 0.0 {
            "f64::INFINITY".to_string()
        } else {
            "f64::NEG_INFINITY".to_string()
        }
    } else {
        format!("{f:?}f64")
    }
}

pub(crate) fn cmp_name(op: BinOp) -> &'static str {
    match op {
        BinOp::Eq => "Eq",
        BinOp::Ne => "NotEq",
        BinOp::Lt => "Lt",
        BinOp::Le => "LtEq",
        BinOp::Gt => "Gt",
        BinOp::Ge => "GtEq",
        _ => unreachable!("not a comparison"),
    }
}

pub(crate) fn binop_name(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "Add",
        BinOp::Sub => "Sub",
        BinOp::Mul => "Mul",
        BinOp::Div => "Div",
        BinOp::Mod => "Mod",
        BinOp::BitAnd => "BitAnd",
        BinOp::BitOr => "BitOr",
        BinOp::BitXor => "BitXor",
        BinOp::Shl => "Shl",
        BinOp::Shr => "Shr",
        _ => unreachable!("not an arithmetic operator"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn float_literals_round_trip() {
        assert_eq!(float_literal(1.0), "1.0f64");
        assert_eq!(float_literal(f64::NAN), "f64::NAN");
        assert_eq!(float_literal(f64::NEG_INFINITY), "f64::NEG_INFINITY");
    }
}
